// Image — Gtk.Image
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles image with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { IconSize } from "@/lib/enums"

export interface ImageProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** utf8, from Gtk.Image */
  file?: string

  /** Gio.Icon, from Gtk.Image */
  gicon?: ReactNode

  /** utf8, from Gtk.Image */
  iconName?: string

  /** IconSize, from Gtk.Image */
  iconSize?: IconSize

  /** Gdk.Paintable, from Gtk.Image */
  paintable?: ReactNode

  /** gint, from Gtk.Image */
  pixelSize?: number

  /** utf8, from Gtk.Image */
  resource?: string

  /** gboolean, from Gtk.Image */
  useFallback?: boolean
}

export function Image({ className, children }: ImageProps) {
  return (
    <div className={cn("p-1", "m-1.5", "bg-[image:radial-gradient(farthest-side,var(--accent-color)_96%,transparent)]", "bg-[size:6px_6px]", "bg-no-repeat", "bg-[position:left_3px]", "opacity-70", "transition-[background,box-shadow]", "duration-200", "ease-[cubic-bezier(0.25,0.46,0.45,0.94)]", "[filter:drop-shadow(0px_1px_1px_RGB(0_0_6/30%))]", "bg-[color-mix(in_srgb,var(--thumbnail-bg-color)_calc(0.8_*_75%),currentColor_calc(0.2_*_75%))]", "rounded-full", "min-w-6", "min-h-6", className)}>
      {children}
    </div>
  )
}
